/**
 * Responsive campaign images (AVIF > WebP, several widths, art-directed for phones).
 * Files are generated by scripts/optimize-images.mjs into /public/img.
 * `priority` marks the one image that is the page's LCP: eager + high fetch priority.
 */
const src = (id, w, ext, mobile) => `/img/hero-${id}${mobile ? '-m' : ''}-${w}.${ext}`;
const set = (id, widths, ext, mobile) => widths.map((w) => `${src(id, w, ext, mobile)} ${w}w`).join(', ');

export function HeroPicture({ id, alt = '', priority = false, pos, sizes = '100vw' }) {
  return (
    <picture>
      <source media="(max-width: 767px)" type="image/avif" srcSet={set(id, [480, 780], 'avif', true)} sizes={sizes} />
      <source media="(max-width: 767px)" type="image/webp" srcSet={set(id, [480, 780], 'webp', true)} sizes={sizes} />
      <source type="image/avif" srcSet={set(id, [960, 1440, 1920], 'avif')} sizes={sizes} />
      <source type="image/webp" srcSet={set(id, [960, 1440, 1920], 'webp')} sizes={sizes} />
      <img
        src={src(id, 1440, 'webp')} alt={alt} width="1920" height="1080"
        loading={priority ? 'eager' : 'lazy'} fetchPriority={priority ? 'high' : 'auto'} decoding="async"
        style={pos ? { '--pos': pos } : undefined}
      />
    </picture>
  );
}

/** Tall portrait crop (the phone art direction) for chapter panels. */
export function PortraitPicture({ id, alt = '', pos, sizes = '(max-width: 900px) 78vw, 26vw' }) {
  return (
    <picture>
      <source type="image/avif" srcSet={set(id, [480, 780], 'avif', true)} sizes={sizes} />
      <source type="image/webp" srcSet={set(id, [480, 780], 'webp', true)} sizes={sizes} />
      <img src={src(id, 780, 'webp', true)} alt={alt} width="780" height="1527" loading="lazy" decoding="async" style={pos ? { '--pos': pos } : undefined} />
    </picture>
  );
}
